import { createHash } from "node:crypto"
import * as cheerio from "cheerio"

/*
 * Fetches and parses a CampTix attendee list.
 *
 * There is no JSON API for attendees -- `/wp-json/wp/v2/tix_attendee` 404s, and the REST
 * index only registers `speakers` and `sessions`. HTML parsing is the only route, so this
 * module owns every assumption about the page structure. If WordCamp ever changes the
 * markup, this file is the only thing that needs to move.
 *
 * The markup is machine-generated by the [camptix_attendees] shortcode and very regular:
 *
 *   #tix-attendees > ul.tix-attendee-list > li
 *       img.avatar                       src=".../avatar/<sha256-of-email>?s=96..."
 *       .tix-field.tix-attendee-name     > .tix-first + .tix-last
 *       .tix-field.tix-job-title
 *       a.tix-field.tix-attendee-url     href + link text
 *
 * The two `tix-badge-*-name-*` fields are deliberately ignored: their class names are
 * derived from the camp-specific registration question text ("this will be printed on
 * your name badge"), so they differ per event and duplicate first/last anyway.
 */

const USER_AGENT = "WordCampAttendeeTracker/1.0 (+https://github.com/dream-encode; polls once per 30min)"
const FETCH_TIMEOUT_MS = 45_000

/**
 * Stable identity for an attendee.
 *
 * The Gravatar hash alone is tempting -- it is the SHA-256 of the attendee email, so it is
 * public, stable, and free. But it is NOT unique: WCUS 2026 has 633 attendees across only
 * 624 distinct hashes, because people buy multiple tickets under one email. Keying on the
 * hash alone would collapse those into one record and silently swallow real arrivals, so
 * the name is folded in.
 *
 * @since  [NEXT_VERSION]
 *
 * @param  {string} gravatarHash Gravatar hash from the avatar URL, may be empty.
 * @param  {string} first        Attendee first name.
 * @param  {string} last         Attendee last name.
 * @return {string}              Hex SHA-256 identity key.
 */
export const attendeeKey = ( gravatarHash, first, last ) => {
	const seed = [ gravatarHash, first.toLowerCase(), last.toLowerCase() ].join( "|" )

	return createHash( "sha256" ).update( seed ).digest( "hex" )
}

/**
 * Collapses runs of whitespace and trims. CampTix pads its fields with newlines and tabs.
 *
 * @since  [NEXT_VERSION]
 *
 * @param  {string} value Raw text from the page.
 * @return {string}       Normalized text.
 */
const clean = ( value ) => {
	return ( value || "" ).replace( /\s+/g, " " ).trim()
}

/**
 * Undoes CampTix's URL escaping of the company label.
 *
 * The "company or personal website" field is a free-text box that many people fill with a
 * company name rather than a URL. CampTix runs the value through URL escaping for both the
 * href and the link text, so "Haymarket Media" is published as "Haymarket%20Media" -- 61 of
 * the 628 WCUS 2026 entries are affected. The href stays as-is (it is rejected as unusable
 * at render time anyway); only the human-facing label is decoded.
 *
 * Left untouched when decoding fails, which is what a literal percent sign does -- a
 * company genuinely named "100% Design" throws here and keeps its original text.
 *
 * @since  [NEXT_VERSION]
 *
 * @param  {string} value Possibly percent-encoded label.
 * @return {string}       Decoded label, or the original when it does not decode.
 */
const decodeLabel = ( value ) => {
	if ( ! value.includes( "%" ) ) {
		return value
	}

	try {
		return decodeURIComponent( value )
	} catch {
		return value
	}
}

/**
 * Fetches the attendee page HTML.
 *
 * The page sends `Cache-Control: must-revalidate, max-age=3` and no ETag, so there is no
 * cheap conditional request available -- every poll is a full ~800KB read.
 *
 * @since  [NEXT_VERSION]
 *
 * @param  {string} url Attendee list URL.
 * @return {Promise<string>} Raw HTML.
 */
export const fetchAttendeePage = async ( url ) => {
	const response = await fetch( url, {
		headers: {
			"user-agent": USER_AGENT,
			accept: "text/html"
		},
		signal: AbortSignal.timeout( FETCH_TIMEOUT_MS )
	} )

	if ( ! response.ok ) {
		throw new Error( `Fetch failed for ${ url }: HTTP ${ response.status } ${ response.statusText }` )
	}

	return await response.text()
}

/**
 * Parses attendee records out of the page HTML.
 *
 * Throws rather than returning an empty list when the structure is missing. An empty
 * result is indistinguishable from "everyone left", and treating a broken fetch as a mass
 * departure would destroy every recorded `added_at` -- see the drop guard in poll.js.
 *
 * @since  [NEXT_VERSION]
 *
 * @param  {string} html Raw page HTML.
 * @return {Array<object>} Parsed attendee records, in page order.
 */
export const parseAttendees = ( html ) => {
	const $ = cheerio.load( html )
	const container = $( "#tix-attendees" )

	if ( 0 === container.length ) {
		throw new Error( "Parse failed: no #tix-attendees container. The page structure changed, or this was an error/challenge page." )
	}

	const rows = container.find( "ul.tix-attendee-list > li" )

	if ( 0 === rows.length ) {
		throw new Error( "Parse failed: #tix-attendees present but contains zero attendee rows." )
	}

	const attendees = []

	rows.each( ( _index, element ) => {
		const row = $( element )
		const first = clean( row.find( ".tix-attendee-name .tix-first" ).text() )
		const last = clean( row.find( ".tix-attendee-name .tix-last" ).text() )

		// A row with no name at all is not a person we can track or key on.
		if ( "" === first && "" === last ) {
			return
		}

		const avatarSrc = row.find( "img.avatar" ).attr( "src" ) || ""
		const hashMatch = avatarSrc.match( /\/avatar\/([0-9a-f]{32,64})/ )
		const gravatarHash = hashMatch ? hashMatch[ 1 ] : ""
		const companyLink = row.find( "a.tix-attendee-url" ).first()

		attendees.push( {
			key: attendeeKey( gravatarHash, first, last ),
			first,
			last,
			job_title: clean( row.find( ".tix-job-title" ).text() ),
			company: decodeLabel( clean( companyLink.text() ) ),
			company_url: companyLink.attr( "href" ) || "",
			gravatar_hash: gravatarHash
		} )
	} )

	if ( 0 === attendees.length ) {
		throw new Error( "Parse failed: attendee rows found but none yielded a name." )
	}

	return attendees
}

/**
 * Convenience wrapper: fetch then parse.
 *
 * @since  [NEXT_VERSION]
 *
 * @param  {string} url Attendee list URL.
 * @return {Promise<Array<object>>} Parsed attendee records.
 */
export const fetchAttendees = async ( url ) => {
	return parseAttendees( await fetchAttendeePage( url ) )
}
